import os

def safe_upload_path(upload_dir: str, filename: str) -> str:
    if not os.path.isabs(upload_dir):
        raise ValueError("Upload directory must be absolute")
    if not os.path.isdir(upload_dir):
        raise ValueError("Upload directory does not exist")
    if not os.access(upload_dir, os.W_OK):
        raise ValueError("Upload directory is not writable")
    if any(char.startswith('../') for char in filename):
        raise ValueError("Filename contains path traversal")
    return os.path.join(upload_dir, filename)
