```python
import os

def safe_upload_path(upload_dir: str, filename: str) -> str:
    if not os.path.isabs(upload_dir):
        raise ValueError("Upload directory must be absolute")
    if not os.path.isdir(upload_dir):
        raise ValueError("Upload directory does not exist or is not a directory")
    if any(os.path.sep * 2 in path for path in [upload_dir, filename]):
        raise ValueError("Filename or upload directory contains path traversal")
    return os.path.join(upload_dir, filename)
